async function generateDocxBuffer(text2, metadata = {}) {
  const title2 = metadata.title || "Naskah Karya Ilmiah (Hasil Humanisasi 4S)";
  const author = metadata.author || "Penulis Karya Ilmiah";
  const rawParagraphs = text2.split(/\n\s*\n/).filter((p3) => p3.trim().length > 0);
  const docParagraphs = [];
  for (const block of rawParagraphs) {
    const trimmed = block.trim();
    const isChapterHeading = /^BAB\s+[IVXLCDM]+/i.test(trimmed) || /^(DAFTAR\s+PUSTAKA|ABSTRAK|ABSTRACT)/i.test(trimmed);
    if (isChapterHeading) {
      const lines = trimmed.split("\n");
      for (const line of lines) {
        docParagraphs.push(
          new Paragraph({
            children: [
              new TextRun({
                text: line.trim(),
                font: "Times New Roman",
                bold: true,
                size: 24
                // 12pt
              })
            ],
            alignment: AlignmentType.CENTER,
            spacing: { before: 240, after: 120, line: 360 }
          })
        );
      }
    } else {
      docParagraphs.push(
        new Paragraph({
          children: [
            new TextRun({
              text: trimmed.replace(/\n/g, " "),
              font: "Times New Roman",
              size: 24
              // 12pt
            })
          ],
          indent: { firstLine: 567 },
          // 1 cm indent (567 twips)
          alignment: AlignmentType.JUSTIFIED,
          spacing: { line: 360, after: 120 }
          // 1.5 line spacing
        })
      );
    }
  }
  const doc = new File2({
    title: title2,
    creator: author,
    description: "Naskah karya ilmiah terbebas plagiasi dan AI dengan metode 4S Standar Nasional",
    sections: [
      {
        properties: {
          page: {
            margin: {
              top: 2268,
              // 4 cm (4 * 567 twips)
              left: 2268,
              // 4 cm
              bottom: 1701,
              // 3 cm (3 * 567 twips)
              right: 1701
              // 3 cm
            }
          }
        },
        children: docParagraphs
      }
    ]
  });
  return await Packer.toBuffer(doc);
}
